+/**
+ * Create a workbook from parsed CSV records in a single transaction
+ * (REQ-1-3-1 / contract increment A-1). Either the workbook, its Sheet1 and
+ * every cell land together, or nothing does.
+ *
+ * Structure (contract increment A-2): the worksheet is never smaller than the
+ * default 6 x 26 structure, so an empty or tiny CSV still yields an editable
+ * worksheet with a valid A1 selection and a renderable grid. Both bounds come
+ * from the single shared source in `config.js` (contract v1.3 A-2).
+ *
+ * Import footprint (contract v1.3 / increment A-4): `min_rows`/`min_cols`
+ * record the CSV's own row/column counts (after trailing blank lines are
+ * clipped and ragged rows are padded), so the CSV export can keep trailing
+ * empty fields that lie outside the non-empty bounding box. Those two columns
+ * are written here and nowhere else: structure operations never touch them.
+ *
+ * @param {Db} db
+ * @param {string} name
+ * @param {string[][]} records
+ * @returns {WorkbookSnapshot}
+ */
+export function createWorkbookFromCsv(db, name, records) {
+  const id = newId('wb');
+  const worksheetId = newId('ws');
+  const at = nowIso();
+  const rowCount = Math.max(records.length, DEFAULT_ROW_COUNT);
+  const colCount = Math.max(csvColumnCount(records), DEFAULT_COL_COUNT);
+  const minRows = records.length;
+  const minCols = csvColumnCount(records);
+
+  db.transaction(() => {
+    db.prepare('INSERT INTO workbooks (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)').run(
+      id,
+      name,
+      at,
+      at,
+    );
+    db.prepare(
+      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, min_rows, min_cols, last_active, last_selection)
+       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
+    ).run(
+      worksheetId,
+      id,
+      'Sheet1',
+      0,
+      rowCount,
+      colCount,
+      minRows,
+      minCols,
+      1,
+      JSON.stringify(DEFAULT_SELECTION),
+    );
+    const insert = db.prepare(
+      'INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)',
+    );
+    for (let row = 0; row < records.length; row += 1) {
+      const record = records[row];
+      for (let col = 0; col < record.length; col += 1) {
+        const raw = record[col];
+        // Same convention as every other write path: an empty field has no row.
+        if (raw !== '') insert.run(worksheetId, row, col, raw);
+      }
+    }
+  })();
+
+  const snapshot = getWorkbookSnapshot(db, id);
+  if (!snapshot) throw new Error('Failed to create workbook from CSV');
+  return snapshot;
+}
