  it('answers with the same shape as GET /api/workbooks/:id and keeps updatedAt on activation', async () => {
    const app = appFor(freshDb());
    const before = await snapshot(app);
    const res = await request(app)
      .patch(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET2_ID}`)
      .send({ isActive: true });
    expect(res.status).toBe(200);
    expect(Object.keys(res.body).sort()).toEqual(['id', 'name', 'updatedAt', 'worksheets']);
    expect(res.body.worksheets).toHaveLength(2);
    expect(res.body.worksheets[0]).toHaveProperty('cells');
    expect(res.body.worksheets[1].isActive).toBe(true);
